minimal_example.code:
-- планировщик оценивает по статистике, сколько строк вернёт условие
EXPLAIN SELECT * FROM orders WHERE status = 'shipped';
-- Seq Scan on orders  (cost=0.00..18334.00 rows=412000 width=64)
--   Filter: (status = 'shipped')
-- rows=412000 -- оценка кардинальности из pg_stats (most_common_vals)

-- посмотреть, на что опирается планировщик:
SELECT n_distinct, most_common_vals, correlation
FROM pg_stats WHERE tablename = 'orders' AND attname = 'status';

-- после массовой загрузки статистику обновляют явно
ANALYZE orders;

